// Routes ESPHome MQTT state from the Dometic bridge to the Victron virtual devices.
// Learns the bridge's topic prefix (e.g. dometic/fjx7-bridge) from its status topic.
const t = msg.topic, p = String(msg.payload);
const m = t.match(/^(.*)\/(status|climate\/ac\/[a-z_]+\/state|sensor\/[a-z_]+\/state|select\/adaptive_power\/state)$/);
if (!m) return null;
const base = m[1], leaf = m[2];
flow.set('fjx7_base', base);
const MODES = ['cool','heat','heat_cool','fan_only','dry'];
const AP = ['4A','5A','6A','7A','Unlimited'];
const out = [null,null,null,null,null];
switch (leaf) {
  case 'status':
    node.status({fill: p === 'online' ? 'green' : 'red', shape:'dot', text: base + ': ' + p});
    return null;
  case 'climate/ac/mode/state': {
    out[0] = {payload: {'SwitchableOutput/output_1/State': p === 'off' ? 0 : 1}};
    const i = MODES.indexOf(p);
    if (i >= 0) { flow.set('fjx7_last_mode', p); out[1] = {payload: {'SwitchableOutput/output_1/Dimming': i}}; }
    break;
  }
  case 'climate/ac/target_temperature/state':
    if (!isNaN(parseFloat(p))) out[2] = {payload: {'SwitchableOutput/output_1/Dimming': parseFloat(p)}};
    break;
  case 'climate/ac/current_temperature/state':
    if (!isNaN(parseFloat(p))) out[2] = {payload: {'SwitchableOutput/output_1/Measurement': parseFloat(p)}};
    break;
  case 'sensor/temperature/state':
    if (!isNaN(parseFloat(p))) out[4] = {payload: {'Temperature': parseFloat(p)}};
    break;
  case 'select/adaptive_power/state': {
    const i = AP.indexOf(p);
    if (i >= 0) out[3] = {payload: {'SwitchableOutput/output_1/Dimming': i}};
    break;
  }
}
return out;

// Turns a change made on the GX / VRM into an MQTT command for the bridge.
function toBridge(suffix, payload) {
  const base = flow.get('fjx7_base');
  if (!base) { node.warn('Bridge not seen yet (no MQTT state received) - command dropped'); return null; }
  return {topic: base + '/' + suffix, payload: payload};
}
const on = Number(msg.payload) === 1;
const mode = on ? (flow.get('fjx7_last_mode') || 'cool') : 'off';
return toBridge('climate/ac/mode/command', mode);

// Turns a change made on the GX / VRM into an MQTT command for the bridge.
function toBridge(suffix, payload) {
  const base = flow.get('fjx7_base');
  if (!base) { node.warn('Bridge not seen yet (no MQTT state received) - command dropped'); return null; }
  return {topic: base + '/' + suffix, payload: payload};
}
const MODES = ['cool','heat','heat_cool','fan_only','dry'];
const mode = MODES[Number(msg.payload)];
if (!mode) return null;
flow.set('fjx7_last_mode', mode);
return toBridge('climate/ac/mode/command', mode);

// Turns a change made on the GX / VRM into an MQTT command for the bridge.
function toBridge(suffix, payload) {
  const base = flow.get('fjx7_base');
  if (!base) { node.warn('Bridge not seen yet (no MQTT state received) - command dropped'); return null; }
  return {topic: base + '/' + suffix, payload: payload};
}
const t = Number(msg.payload);
if (isNaN(t)) return null;
return toBridge('climate/ac/target_temperature/command', String(Math.min(31, Math.max(16, t))));

// Turns a change made on the GX / VRM into an MQTT command for the bridge.
function toBridge(suffix, payload) {
  const base = flow.get('fjx7_base');
  if (!base) { node.warn('Bridge not seen yet (no MQTT state received) - command dropped'); return null; }
  return {topic: base + '/' + suffix, payload: payload};
}
const AP = ['4A','5A','6A','7A','Unlimited'];
const v = AP[Number(msg.payload)];
if (!v) return null;
return toBridge('select/adaptive_power/command', v);
